15	/// Maximum allowed length (in characters) for a feed's `title`, matching
16	/// the client-side `maxlength` on the create-feed form. Enforced here too
17	/// since the client-side check is trivially bypassed with a direct POST.
18	const MAX_TITLE_LEN: usize = 500;
19	
20	/// Validates a user-supplied feed title. Rejects empty/whitespace-only
21	/// titles and titles longer than [`MAX_TITLE_LEN`] characters.
22	fn validate_title(title: &str) -> Result<(), KtnError> {
23	    if title.trim().is_empty() {
24	        return Err(KtnError::BadRequest("Title must not be empty".to_owned()));
25	    }
26	
27	    if title.chars().count() > MAX_TITLE_LEN {
28	        return Err(KtnError::BadRequest(format!(
29	            "Title must not exceed {} characters",
30	            MAX_TITLE_LEN
31	        )));
32	    }
33	
34	    Ok(())
35	}
