37	pub async fn create_feed(
38	    State(pool): State<Pool>,
39	    form: Form<CreateFeedForm>,
40	) -> Result<impl IntoResponse, KtnError> {
41	    debug!("{:?}", form);
42	
43	    validate_title(&form.title)?;
44	
45	    let mut form = NewFeed {
46	        title: form.title.to_owned(),
47	        reference: None,
48	    };
49	    let reference = form.save(&pool).await.map_err(|e| {
50	        debug!("Couldn't save new feed: {}", e);
51	        KtnError::InternalServerError
52	    })?;
53	
54	    Ok(Redirect::to(&format!("/feeds/{}.html", reference)))
55	}
