72	pub async fn get_feed_html(
73	    Path(reference): Path<String>,
74	    State(pool): State<Pool>,
75	) -> Result<Response, KtnError> {
76	    let no_ext: &str = reference.split(".html").next().unwrap();
77	    let title = match Feed::get_title_given_reference(no_ext, &pool).await {
78	        Ok(t) => t,
79	        _ => {
80	            debug!("No Feed with reference \"{}\" found.", no_ext);
81	            return Err(KtnError::NotFoundError);
82	        }
83	    };
84	
85	    let feed = NewFeed {
86	        reference: Some(no_ext.to_owned()),
87	        title,
88	    };
89	
90	    let template = feed.created_template().render();
91	
92	    match template {
93	        Ok(template) => Ok(Response::builder()
94	            .status(StatusCode::OK)
95	            .header(
96	                http::header::CONTENT_TYPE,
97	                http::HeaderValue::from_static("text/html; charset=utf-8"),
98	            )
99	            .body(Body::from(template))
100	            .unwrap()),
101	        _ => Err(KtnError::InternalServerError),
102	    }
103	}
