105	pub async fn get_feed_xml(
106	    Path(reference): Path<String>,
107	    State(pool): State<Pool>,
108	) -> Result<Response, KtnError> {
109	    let no_ext: &str = reference.split(".xml").next().unwrap();
110	    let entries = match Entry::find_by_reference(no_ext, &pool).await {
111	        Ok(entries) => entries,
112	        Err(_) => return Err(KtnError::NotFoundError),
113	    };
114	
115	    // Since we create "Sentinel" entries on Feed creation, this should never
116	    // be reached, but just in case.
117	    if entries.is_empty() {
118	        return Err(KtnError::NotFoundError);
119	    }
120	
121	    let title = match Feed::get_title_given_reference(no_ext, &pool).await {
122	        Ok(title) => title,
123	        _ => String::from("No feed title found"),
124	    };
125	
126	    let template = FeedAtomTemplate {
127	        web_url: web_url(),
128	        email_domain: email_domain(),
129	        feed_title: title,
130	        feed_reference: no_ext.to_owned(),
131	        entries,
132	    }
133	    .render();
134	
135	    match template {
136	        Ok(template) => Ok(Response::builder()
137	            .status(StatusCode::OK)
138	            .header(
139	                http::header::CONTENT_TYPE,
140	                http::HeaderValue::from_static(
141	                    "application/atom+xml; charset=utf-8",
142	                ),
143	            )
144	            .body(Body::from(template))
145	            .unwrap()),
146	        _ => Err(KtnError::InternalServerError),
147	    }
148	}
