50	    /// Returns a [`Feed`]'s `title` given its `reference`.
51	    pub async fn get_title_given_reference(
52	        reference: &str,
53	        pool: &Pool,
54	    ) -> Result<String, sqlx::Error> {
55	        let (title,): (String,) =
56	            sqlx::query_as("SELECT title FROM feeds WHERE reference = $1")
