102	impl NewFeed {
103	    fn new_reference() -> String {
104	        Alphanumeric
105	            .sample_string(&mut rand::thread_rng(), 16)
106	            .to_lowercase()
107	    }
108	
109	    /// References are a random 16-char alphanumeric string (36^16 possible
110	    /// values), so collisions are vanishingly rare but not impossible. One
111	    /// retry with a freshly generated reference is enough to close the gap.
112	    const MAX_SAVE_ATTEMPTS: u32 = 2;
113	
114	    pub async fn save(
115	        &mut self,
116	        pool: &Pool,
117	    ) -> Result<String, Box<dyn Error>> {
118	        let mut attempt = 0;
119	
120	        loop {
121	            attempt += 1;
122	            let reference = self
123	                .reference
124	                .get_or_insert_with(NewFeed::new_reference)
125	                .to_owned();
126	
127	            let content = SentinelTemplate {
128	                email_domain: email_domain(),
129	                reference: reference.clone(),
130	                title: self.title.clone(),
131	                web_url: web_url(),
132	            }
133	            .render()
134	            .map_err(|e| {
135	                debug!("Couldn't render SentinelTemplate: {}", e);
